using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    [McpServerTool, Description("Fetches data from the external API for a given resource ID.")]
    public static async Task<string> FetchExternalData(
        IHttpClientFactory httpClientFactory,
        [Description("The resource identifier to look up")] string resourceId,
        CancellationToken cancellationToken)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt to summarize the provided text.")]
    public static string Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return $"""
            Please summarize the following text in a {style} style.

            Text:
            {content}
            """;
    }
}

